CREATE TYPE "MaterialType" AS ENUM ('QUESTION_BANK', 'SHORT_NOTE', 'FULL_BOOK');
CREATE TYPE "SubscriptionStatus" AS ENUM ('ACTIVE', 'EXPIRED', 'CANCELED', 'PENDING');
CREATE TYPE "MessageRole" AS ENUM ('USER', 'ASSISTANT');
CREATE TABLE "Company" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Company_pkey" PRIMARY KEY ("id"));
CREATE TABLE "University" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "University_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Course" ("id" UUID NOT NULL, "universityId" UUID NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Course_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StudyMaterial" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "universityId" UUID NOT NULL, "courseId" UUID NOT NULL, "title" TEXT NOT NULL, "type" "MaterialType" NOT NULL, "isPublished" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StudyMaterial_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StudyChunk" ("id" UUID NOT NULL, "materialId" UUID NOT NULL, "content" TEXT NOT NULL, "pageNumber" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StudyChunk_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Student" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "phone" TEXT NOT NULL, "displayName" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Student_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Subscription" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "status" "SubscriptionStatus" NOT NULL DEFAULT 'PENDING', "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "provider" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Subscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChatSession" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "universityId" UUID NOT NULL, "courseId" UUID NOT NULL, "title" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ChatSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChatMessage" ("id" UUID NOT NULL, "sessionId" UUID NOT NULL, "role" "MessageRole" NOT NULL, "content" TEXT NOT NULL, "sources" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ChatMessage_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Company_slug_key" ON "Company"("slug");
CREATE UNIQUE INDEX "University_companyId_slug_key" ON "University"("companyId", "slug");
CREATE INDEX "University_companyId_idx" ON "University"("companyId");
CREATE UNIQUE INDEX "Course_universityId_slug_key" ON "Course"("universityId", "slug");
CREATE INDEX "Course_universityId_idx" ON "Course"("universityId");
CREATE INDEX "StudyMaterial_companyId_universityId_courseId_isPublished_idx" ON "StudyMaterial"("companyId", "universityId", "courseId", "isPublished");
CREATE INDEX "StudyChunk_materialId_idx" ON "StudyChunk"("materialId");
CREATE UNIQUE INDEX "Student_companyId_phone_key" ON "Student"("companyId", "phone");
CREATE INDEX "Student_companyId_idx" ON "Student"("companyId");
CREATE INDEX "Subscription_studentId_status_endsAt_idx" ON "Subscription"("studentId", "status", "endsAt");
CREATE INDEX "ChatSession_studentId_createdAt_idx" ON "ChatSession"("studentId", "createdAt");
CREATE INDEX "ChatMessage_sessionId_createdAt_idx" ON "ChatMessage"("sessionId", "createdAt");
ALTER TABLE "University" ADD CONSTRAINT "University_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Course" ADD CONSTRAINT "Course_universityId_fkey" FOREIGN KEY ("universityId") REFERENCES "University"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StudyMaterial" ADD CONSTRAINT "StudyMaterial_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StudyMaterial" ADD CONSTRAINT "StudyMaterial_universityId_fkey" FOREIGN KEY ("universityId") REFERENCES "University"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StudyMaterial" ADD CONSTRAINT "StudyMaterial_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StudyChunk" ADD CONSTRAINT "StudyChunk_materialId_fkey" FOREIGN KEY ("materialId") REFERENCES "StudyMaterial"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Student" ADD CONSTRAINT "Student_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Subscription" ADD CONSTRAINT "Subscription_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ChatSession" ADD CONSTRAINT "ChatSession_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ChatMessage" ADD CONSTRAINT "ChatMessage_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "ChatSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE INDEX "StudyChunk_content_fts_idx" ON "StudyChunk" USING GIN (to_tsvector('simple', "content"));
